 39→mn89304_vga_device::mn89304_vga_device(const machine_config &mconfig, const char *tag, device_t *owner, uint32_t clock)
 40→	: svga_device(mconfig, MN89304_VGA, tag, owner, clock)
 41→{
 42→	// ...
 43→}
 44→
 45→void mn89304_vga_device::device_reset()
 46→{
 47→	svga_device::device_reset();
 48→	svga.rgb8_en = 1;
 49→}
 50→
 51→// sets up mode 0, by default it will throw 155 Hz, assume divided by 3
 52→void mn89304_vga_device::recompute_params()
 53→{
 54→	u8 xtal_select = (vga.miscellaneous_output & 0x0c) >> 2;
 55→	int xtal;
 56→
 57→	switch(xtal_select & 3)
 58→	{
 59→		case 0: xtal = XTAL(25'174'800).value() / 3; break;
 60→		case 1: xtal = XTAL(28'636'363).value() / 3; break;
 61→		case 2:
 62→		default:
 63→			throw emu_fatalerror("MN89304: setup ext. clock select");
 64→	}
 65→
 66→	recompute_params_clock(1, xtal);
 67→}
 68→
 69→
 70→void mn89304_vga_device::palette_update()
 71→{
 72→	// 4bpp RAMDAC
 73→	for (int i = 0; i < 256; i++)
 74→	{
 75→		set_pen_color(
 76→			i,
 77→			pal4bit(vga.dac.color[3*(i & vga.dac.mask) + 0]),
 78→			pal4bit(vga.dac.color[3*(i & vga.dac.mask) + 1]),
 79→			pal4bit(vga.dac.color[3*(i & vga.dac.mask) + 2])
 80→		);
 81→	}
 82→}
 83→
 84→uint16_t mn89304_vga_device::offset()
 85→{
 86→	return svga_device::offset() << 3;
 87→}
