void Stack::push(uint16_t value)
{
	if (*m_sp == 0xFF)
	{
		m_overflow = true;
	}
	else if (*m_sp == 0x00 && m_overflow)
	{
		printf("ERROR: stack overflow\n");
		//TODO: reset();
	}
	m_stacked_values[(*m_sp)++] = value;
}

