 37→void Stack::push(uint16_t value)
 38→{
 39→	if (*m_sp == 0xFF)
 40→	{
 41→		m_overflow = true;
 42→	}
 43→	else if (*m_sp == 0x00 && m_overflow)
 44→	{
 45→		printf("ERROR: stack overflow\n");
 46→		//TODO: reset();
 47→	}
 48→	m_stacked_values[(*m_sp)++] = value;
 49→}
