 51→
 52→uint16_t Stack::pop(){
 53→	if (*m_sp == 0x00 && !m_overflow){
 54→		printf("ERROR: stack underflow\n");
 55→		//TODO: reset();
 56→	} else {
 57→		m_overflow = false;
 58→	}
 59→	return m_stacked_values[--(*m_sp)];
 60→}
