 93→void another_world_cpu_device::checkThreadRequests()
 94→{
 95→	//Check if a part switch has been requested.
 96→	if (m_requestedNextPart != 0)
 97→	{
 98→		initForPart(m_requestedNextPart);
 99→		m_requestedNextPart = 0;
100→	}
101→
102→	for (int i=0; i<NUM_THREADS; i++)
103→	{
104→		Thread* thread = &m_threads[i];
105→
106→		thread->state = thread->requested_state;
107→
108→		if (thread->requested_PC != NO_REQUEST)
109→		{
110→			if (thread->requested_PC == DELETE_THIS_THREAD)
111→				thread->PC = INACTIVE_THREAD;
112→			else
113→				thread->PC = thread->requested_PC;
114→
115→			thread->requested_PC = NO_REQUEST;
116→		}
117→	}
118→}
