121→void another_world_cpu_device::input_updatePlayer()
122→{
123→	int16_t lr = 0;
124→	int16_t m = 0;
125→	int16_t ud = 0;
126→	int8_t input = m_read_input();
127→
128→	write_vm_variable(VM_VARIABLE_LAST_KEYCHAR, m_read_keyboard());
129→
130→	if (m_currentPartId != GAME_PART(0)
131→	    && m_currentPartId != GAME_PART(9)
132→	    && BIT(input, 4))
133→		m_requestedNextPart = GAME_PART(9);
134→
135→	if (BIT(input, 2))
136→	{
137→		lr = 1;
138→		m |= 1;
139→	}
140→
141→	if (BIT(input, 3))
142→	{
143→		lr = -1;
144→		m |= 2;
145→	}
146→
147→	if (BIT(input, 0))
148→	{
149→		ud = 1;
150→		m |= 4;
151→	}
152→
153→	if (BIT(input, 1))
154→	{
155→		write_vm_variable(VM_VARIABLE_HERO_POS_UP_DOWN, -1);
156→		ud = -1;
157→		m |= 8;
158→	}
159→	else
160→	{
161→		write_vm_variable(VM_VARIABLE_HERO_POS_UP_DOWN, ud);
162→	}
163→
164→	write_vm_variable(VM_VARIABLE_HERO_POS_JUMP_DOWN, ud);
165→	write_vm_variable(VM_VARIABLE_HERO_POS_LEFT_RIGHT, lr);
166→	write_vm_variable(VM_VARIABLE_HERO_POS_MASK, m);
167→
168→	int16_t button = 0;
169→	if (BIT(input, 7))
170→	{
171→		button = 1;
172→		m |= 0x80;
173→	}
174→
175→	write_vm_variable(VM_VARIABLE_HERO_ACTION, button);
176→	write_vm_variable(VM_VARIABLE_HERO_ACTION_POS_MASK, m);
177→}
