180→void another_world_cpu_device::nextThread()
181→{
182→
183→#ifdef DUMP_VM_EXECUTION_LOG
184→	std::ostream log_stream(&m_log_filebuf);
185→	log_stream << "\n";
186→#endif
187→
188→	input_updatePlayer();
189→	Thread* current;
190→	do {
191→		if (++m_currentThread == NUM_THREADS)
192→		{
193→
194→#ifdef DUMP_VM_EXECUTION_LOG
195→			log_stream << "=== NEW FRAME ===\n";
196→#endif
197→			/* End of Frame */
198→			m_currentThread = 0;
199→			checkThreadRequests();
200→			((another_world_vm_state*) owner())->updateDisplay(0xFE);
201→		}
202→		current = &m_threads[m_currentThread];
203→	}
204→	while(current->state == FROZEN || current->PC == INACTIVE_THREAD);
205→
206→	PC = current->PC;
207→}
