304→#ifdef VM_HACK_INIT_VAR_54_WITH_81
305→	// Without this, the Interplay logo does not show up
306→	// while running the MSDOS bytecode:
307→	write_vm_variable(0x54, 0x0081);
308→
309→	//TODO: check if this var is read or written anywhere
310→	// else during gameplay. Ideally run the whole game with
311→	// a watchpoint monitoring this one.
312→
313→	// Some clues:
314→	// [14 - 007F]: 0A jl [HACK_VAR_54], 0x80, 0x00BF
315→	// [14 - 00E4]: 0A jge [HACK_VAR_54], 0x80, 0x00F6
316→	// [14 - 0165]: 14 and [HACK_VAR_54], 0x0001
317→	// [14 - 0169]: 0A je [HACK_VAR_54], 0x00, 0x0199
318→	// [18 - 3EAB]: 00 mov [HACK_VAR_54], 0xFFFB
319→#endif
320→
321→#ifdef BYPASS_PROTECTION
322→	//This is a hack to skip the code wheel
323→	write_vm_variable(VM_VARIABLE_HERO_ACTION, 0xFFFF);
324→#endif
325→
326→	write_vm_variable(VM_VARIABLE_RANDOM_SEED, time(0) );
327→}
