339→
340→/* execute one instruction */
341→void another_world_cpu_device::execute_instruction()
342→{
343→	debugger_instruction_hook(PC);
344→	Thread* current = &m_threads[m_currentThread];
345→
346→#ifdef DUMP_VM_EXECUTION_LOG
347→	uint32_t options = 0;
348→	uint8_t _oprom[8], _opram[8];
349→
350→	for (int i=0; i<8; i++) {
351→		_oprom[i] = READ_BYTE_AW(PC+i);
352→		_opram[i] = 0;
353→	}
354→
355→	std::ostream log_stream(&m_log_filebuf);
356→
357→	char tmp[256];
358→	snprintf(tmp, sizeof(tmp), "[%02X - %04X]: %02X ", m_currentThread, PC, READ_BYTE_AW(PC));
359→	log_stream << tmp;
360→
361→	extern CPU_DISASSEMBLE( another_world );
362→	CPU_DISASSEMBLE_NAME(another_world)(this, log_stream, PC, _oprom, _opram, options);
363→	log_stream << "\n";
364→#endif
365→
366→	unsigned char opcode = fetch_byte();
367→
368→	if (opcode & 0x80)
369→	{
370→		uint16_t offset = ((opcode << 8) | fetch_byte()) * 2;
371→
372→		m_useVideo2 = false;
373→		int16_t x = fetch_byte();
374→		int16_t y = fetch_byte();
375→		int16_t h = y - 199;
376→		if (h > 0)
377→		{
378→			y = 199;
379→			x += h;
380→		}
381→
382→		// This switches the polygon database to "cinematic" and probably
383→		// draws a black polygon over all the screen.
384→		((another_world_vm_state*) owner())->setDataBuffer(CINEMATIC, offset);
385→		((another_world_vm_state*) owner())->readAndDrawPolygon(COLOR_BLACK, DEFAULT_ZOOM, VMPoint(x,y));
386→
387→		return;
388→	}
389→
390→	if (opcode & 0x40)
391→	{
392→		int16_t x, y;
393→		uint16_t offset = fetch_word() * 2;
394→		x = fetch_byte();
395→
396→		m_useVideo2 = false;
397→
398→		if (!(opcode & 0x20))
399→		{
400→			if (!(opcode & 0x10))
401→				x = (x << 8) | fetch_byte();
402→			else
403→				x = read_vm_variable(x);
404→		}
405→		else
406→		{
407→		    if (opcode & 0x10)
408→		        x += 0x100;
409→		}
410→
411→		y = fetch_byte();
412→
413→		if (!(opcode & 8))
414→		{
415→			if (!(opcode & 4))
416→				y = (y << 8) | fetch_byte();
417→			else
418→				y = read_vm_variable(y);
419→		}
420→
421→		uint16_t zoom = 0x40;
422→
423→		switch (opcode & 0x03)
424→		{
425→			case 0:
426→				zoom = 0x40;
427→				break;
428→			case 1:
429→				zoom = read_vm_variable(fetch_byte());
430→				break;
431→			case 2:
432→				fetch_byte();
433→				break;
434→			case 3:
435→				m_useVideo2 = true;
436→				zoom = 0x40;
437→				break;
438→		}
439→
440→		((another_world_vm_state*) owner())->setDataBuffer(m_useVideo2 ? VIDEO_2 : CINEMATIC, offset);
441→		((another_world_vm_state*) owner())->readAndDrawPolygon(COLOR_BLACK, zoom, VMPoint(x, y));
442→		return;
443→	}
444→
445→	switch (opcode){
446→		case 0x00: /* movConst */
447→		{
448→			uint8_t variableId = fetch_byte();
449→			int16_t value = fetch_word();
450→			write_vm_variable(variableId, value);
451→			return;
452→		}
453→		case 0x01: /* mov */
454→		{
455→			uint8_t dstVariableId = fetch_byte();
456→			uint8_t srcVariableId = fetch_byte();
457→			uint16_t value = read_vm_variable(srcVariableId);
458→			write_vm_variable(dstVariableId, value);
459→			return;
460→		}
461→		case 0x02: /* add */
462→		{
463→			uint8_t dstVariableId = fetch_byte();
464→			uint8_t srcVariableId = fetch_byte();
465→			uint16_t result = read_vm_variable(dstVariableId);
466→			result += read_vm_variable(srcVariableId);
467→			write_vm_variable(dstVariableId, result);
468→			return;
469→		}
470→		case 0x03: /* addConst */
471→		{
472→			/* TODO: Investigate this:
473→			if (res->currentPartId == 0x3E86 && _scriptPtr.pc == res->segBytecode + 0x6D48)
474→			{
475→				warning("VirtualMachine::op_addConst() hack for non-stop looping gun sound bug");
476→
477→				// The script 0x27 slot 0x17 doesn't stop the gun sound from looping,
478→				// I don't really know why; for now, let's play the 'stopping sound' like
479→				// the other scripts do
480→				//  (0x6D43) jmp(0x6CE5)
481→				//  (0x6D46) break
482→				//  (0x6D47) VAR(6) += -50
483→				snd_playSound(0x5B, 1, 64, 1);
484→			}*/
485→			uint8_t variableId = fetch_byte();
486→			int16_t value = fetch_word();
487→			int16_t result = read_vm_variable(variableId) + value;
488→			write_vm_variable(variableId, result);
489→			return;
490→	        }
491→		case 0x04: /* CALL subroutine instruction */
492→		{
493→			uint16_t addr = fetch_word();
494→			m_stack->push(PC);
495→			PC = addr;
496→			return;
497→		}
498→		case 0x05: /* ret: return from subroutine */
499→		{
500→			PC = m_stack->pop();
501→			return;
502→		}
503→		case 0x06: /* pauseThread instruction (a.k.a. "break") */
504→		{
505→			if (current->requested_PC == NO_REQUEST)
506→				current->requested_PC = PC;
507→
508→			nextThread();
509→			return;
510→		}
511→		case 0x07: /* jmp to address */
512→		{
513→			PC = fetch_word();
514→			return;
515→		}
516→		case 0x08: /* setVect instruction */
517→		{
518→			uint8_t threadId = fetch_byte() & 0x3F;
519→			uint16_t request = fetch_word();
520→
521→			m_threads[threadId].requested_PC = request;
522→			return;
523→		}
524→		case 0x09: /* DJNZ instrucion ('D'ecrement variable value and 'J'ump if 'N'ot 'Z'ero) */
525→		{
526→			uint8_t i = fetch_byte();
527→			uint16_t value = read_vm_variable(i);
528→			value--;
529→			write_vm_variable(i, value);
530→			uint16_t address = fetch_word();
531→			if (value != 0)
532→				PC = address;
533→			return;
534→		}
535→		case 0x0A: /* condJmp */
536→		{
537→			uint8_t subopcode = fetch_byte();
538→			uint8_t v = fetch_byte();
539→			int16_t b = read_vm_variable(v);
540→			uint8_t c = fetch_byte();
541→			int16_t a;
542→
543→			if (subopcode & 0x80)
544→				a = read_vm_variable(c);
545→			else if (subopcode & 0x40)
546→				a = c << 8 | fetch_byte();
547→			else
548→				a = c;
549→
550→#ifdef DUMP_VM_EXECUTION_LOG
551→			char tmp[256];
552→			snprintf(tmp, sizeof(tmp), "subop: 0x%02X v: 0x%02X c: 0x%02X\nvmVar[0x%02X] = 0x%04X\n", subopcode, v, c, v, b);
553→			log_stream << tmp;
554→#endif
555→			// Check if the conditional value is met.
556→			bool expr = false;
557→			switch (subopcode & 7)
558→			{
559→				case 0: // jz
560→					expr = (b == a);
561→					break;
562→				case 1: // jnz
563→					expr = (b != a);
564→					break;
565→				case 2: // jg
566→					expr = (b > a);
567→					break;
568→				case 3: // jge
569→					expr = (b >= a);
570→					break;
571→				case 4: // jl
572→					expr = (b < a);
573→					break;
574→				case 5: // jle
575→					expr = (b <= a);
576→					break;
577→				default:
578→					printf("ERROR: conditional jump: invalid condition (%d)\n", (subopcode & 7));
579→					break;
580→			}
581→
582→			uint16_t offset = fetch_word();
583→			if (expr)
584→				PC = offset;
585→
586→			return;
587→		}
588→		case 0x0B: /* setPalette */
589→		{
590→			uint16_t paletteId = fetch_word();
591→			((another_world_vm_state*) owner())->changePalette((uint8_t ) (paletteId >> 8));
592→			return;
593→		}
594→		case 0x0C: /* resetThread */
595→		{
596→			uint8_t first = fetch_byte();
597→			uint8_t last = fetch_byte();
598→			uint8_t type = fetch_byte();
599→
600→			//Make sure last is within [0, NUM_THREADS-1]
601→			last = last % NUM_THREADS;
602→
603→			if (last < first)
604→			{
605→				printf("ERROR: resetThread with last (%02X) < first (%02X).\n", last, first);
606→				return;
607→			}
608→
609→			switch(type)
610→			{
611→				case RESET_TYPE__UNFREEZE_CHANNELS:
612→					for (int i=first; i<=last; i++)
613→						m_threads[i].requested_state = FROZEN;
614→					break;
615→				case RESET_TYPE__FREEZE_CHANNELS:
616→					for (int i=first; i<=last; i++)
617→						m_threads[i].requested_state = UNFROZEN;
618→					break;
619→				case RESET_TYPE__DELETE_CHANNELS:
620→					for (int i=first; i<=last; i++)
621→						m_threads[i].requested_PC = DELETE_THIS_THREAD;
622→					break;
623→				default:
624→					printf("ERROR: invalid resetThread operation type (%d).\n", type);
625→			}
626→			return;
627→		}
628→		case 0x0D: /* selectVideoPage */
629→		{
630→			uint8_t frameBufferId = fetch_byte();
631→			((another_world_vm_state*) owner())->selectVideoPage(frameBufferId);
632→			return;
633→		}
634→		case 0x0E: /* fillVideoPage */
635→		{
636→			uint8_t pageId = fetch_byte();
637→			uint8_t color = fetch_byte();
638→			((another_world_vm_state*) owner())->fillPage(pageId, color);
639→			return;
640→		}
641→		case 0x0F: /* copyVideoPage */
642→		{
643→			uint8_t srcPageId = fetch_byte();
644→			uint8_t dstPageId = fetch_byte();
645→			((another_world_vm_state*) owner())->copyVideoPage(srcPageId, dstPageId, read_vm_variable(VM_VARIABLE_SCROLL_Y));
646→			return;
647→		}
648→		case 0x10: /* blitFramebuffer */
649→		{
650→			uint8_t pageId = fetch_byte();
651→
652→#ifdef VM_HACK_SWITCH_FROM_INTRO_TO_LAKE
653→			//Nasty hack....was this present in the original assembly  ??!!
654→			//This seems to be necessary for switching from the intro sequence to the lake stage
655→			if (m_currentPartId == GAME_PART(0) && read_vm_variable(0x67) == 1)
656→				write_vm_variable(0xDC, 0x21);
657→
658→			// Some clues:
659→			// [32 - 0D41]: 00 mov [HACK_VAR_67], 0x0001
660→			// [3F - 0D46]: 00 mov [HACK_VAR_67], 0x0000
661→			// [00 - 00B2]: 0A jne [HACK_VAR_DC], 0x21, 0x00B9
662→			// [03 - 00B2]: 0A jne [HACK_VAR_DC], 0x21, 0x00B9
663→			// [3F - 19BB]: 00 mov [HACK_VAR_67], 0x0002
664→			// [3F - 1954]: 0A jne [HACK_VAR_67], [0x65], 0x196F
665→			// [2E - 35E2]: 0A jne [HACK_VAR_67], 0x01, 0x35E1
666→			// [30 - 01F0]: 0A je [HACK_VAR_67], 0x05, 0x01E9
667→			// [30 - 01F6]: 0A je [HACK_VAR_67], 0x02, 0x01E9
668→			// [30 - 0226]: 0A je [HACK_VAR_67], 0x05, 0x0238
669→
670→			// Much more with:
671→			// grep HACK_VAR_67 address_log.txt|sort|uniq|less
672→#endif
673→
674→			// The bytecode will set vmVariables[VM_VARIABLE_PAUSE_SLICES] from 1 to 5
675→			// The virtual machine hence indicate how long the image should be displayed.
676→
677→#ifdef SPEEDUP_VM_EXECUTION
678→			m_icount --;
679→#else
680→			m_icount -= (int) read_vm_variable(VM_VARIABLE_PAUSE_SLICES);
681→#endif
682→
683→#ifdef VM_HACK_BLITFRAMEBUFFER_VAR_F7
684→			//Why ?
685→			write_vm_variable(0xF7, 0x0000);
686→
687→			// Some clues:
688→			// [14 - 0A1B]: 02 add [0x37], [HACK_VAR_F7]
689→#endif
690→			((another_world_vm_state*) owner())->updateDisplay(pageId);
691→			return;
692→		}
693→		case 0x11: /* killThread */
694→		{
695→			current->PC = INACTIVE_THREAD;
696→			nextThread();
697→			return;
698→		}
699→		case 0x12: /* drawString */
700→		{
701→			uint16_t stringId = fetch_word();
702→			uint16_t x = fetch_byte();
703→			uint16_t y = fetch_byte();
704→			uint16_t color = fetch_byte();
705→
706→			((another_world_vm_state*) owner())->draw_string(stringId, x, y, color);
707→			return;
708→		}
709→		case 0x13: /* sub */
710→		{
711→			uint8_t i = fetch_byte();
712→			uint8_t j = fetch_byte();
713→			uint16_t value = read_vm_variable(i);
714→			value -= read_vm_variable(j);
715→			write_vm_variable(i, value);
716→			return;
717→		}
718→		case 0x14: /* and */
719→		{
720→			uint8_t variableId = fetch_byte();
721→			uint16_t value = fetch_word();
722→			uint16_t result = read_vm_variable(variableId) & value;
723→			write_vm_variable(variableId, result);
724→			return;
725→		}
726→		case 0x15: /* or */
727→		{
728→			uint8_t variableId = fetch_byte();
729→			uint16_t value = fetch_word();
730→			uint16_t result = read_vm_variable(variableId) | value;
731→			write_vm_variable(variableId, result);
732→			return;
733→		}
734→		case 0x16: /* shl */
735→		{
736→			uint8_t variableId = fetch_byte();
737→			uint16_t leftShiftValue = fetch_word();
738→			uint16_t result = read_vm_variable(variableId) << leftShiftValue;
739→			write_vm_variable(variableId, result);
740→			return;
741→		}
742→		case 0x17: /* shr */
743→		{
744→			uint8_t variableId = fetch_byte();
745→			uint16_t rightShiftValue = fetch_word();
746→			uint16_t result = read_vm_variable(variableId) >> rightShiftValue;
747→			write_vm_variable(variableId, result);
748→			return;
749→		}
750→		case 0x18: /* play (a.k.a. "playSound") */
751→		{
752→			uint16_t resourceId = fetch_word();
753→			uint8_t freq = fetch_byte();
754→			uint8_t vol = fetch_byte();
755→			uint8_t channel = fetch_byte();
756→			((another_world_vm_state*) owner())->m_mixer->playSound(channel, resourceId, freq, vol);
757→			return;
758→		}
759→		case 0x19: /* load (a.k.a. "updateMemList") */
760→		{
761→			uint16_t resourceId = fetch_word();
762→
763→			if (resourceId == 0)
764→			{
765→				((another_world_vm_state*) owner())->m_mixer->m_player->stop();
766→				((another_world_vm_state*) owner())->m_mixer->stopAll();
767→				//res->invalidateRes();
768→				return;
769→			}
770→
771→#define NUM_MEM_LIST 0x91
772→			if (resourceId > NUM_MEM_LIST)
773→			{
774→				m_requestedNextPart = resourceId;
775→			}
776→			else
777→			{
778→				uint8_t screen_resource_indexes[] = {
779→					0x12, 0x13, 0x43, 0x44,
780→					0x45, 0x46, 0x47, 0x48,
781→					0x49, 0x53, 0x90, 0x91
782→				};
783→				for (int i = 0; i < sizeof(screen_resource_indexes); i++)
784→				{
785→					if (screen_resource_indexes[i]==resourceId)
786→						((another_world_vm_state*) owner())->loadScreen(i);
787→				}
788→			}
789→			return;
790→		}
791→		case 0x1A: /* playMusic */
792→		{
793→			uint16_t resNum = fetch_word();
794→			uint16_t delay = fetch_word();
795→			uint8_t pos = fetch_byte();
796→
797→			if (resNum != 0)
798→			{
799→				int retval = ((another_world_vm_state*) owner())->m_mixer->m_player->loadSfxModule(resNum, delay, pos);
800→				if (!retval) ((another_world_vm_state*) owner())->m_mixer->m_player->start();
801→			}
802→			else if (delay != 0)
803→			{
804→				((another_world_vm_state*) owner())->m_mixer->m_player->setEventsDelay(delay);
805→			}
806→			else
807→			{
808→				((another_world_vm_state*) owner())->m_mixer->m_player->stop();
809→			}
810→			return;
811→		}
812→	}
813→	printf("ERROR: unimplemented opcode: 0x%02X\n", opcode);
814→}
