816→void another_world_cpu_device::initForPart(uint16_t partId)
817→{
818→	((another_world_vm_state*) owner())->m_mixer->m_player->stop();
819→	((another_world_vm_state*) owner())->m_mixer->stopAll();
820→
821→	write_vm_variable(0xE4, 0x14); //why?
822→
823→	((another_world_vm_state*) owner())->setupPart(partId);
824→	m_currentPartId = partId;
825→
826→#ifdef DUMP_VM_EXECUTION_LOG
827→	std::ostream log_stream(&m_log_filebuf);
828→	log_stream << "initForPart " << partId << "\n";
829→#endif
830→	//machine().debug_break();
831→
832→	for (int i=0; i<NUM_THREADS; i++)
833→	{
834→		Thread *thread = &m_threads[i];
835→		thread->requested_PC = NO_REQUEST;
836→		thread->requested_state = NO_REQUEST;
837→		thread->PC = INACTIVE_THREAD;
838→		thread->state = UNFROZEN;
839→	}
840→
841→	m_threads[0].PC = 0x0000;
842→}
