 51→// sets up mode 0, by default it will throw 155 Hz, assume divided by 3
 52→void mn89304_vga_device::recompute_params()
 53→{
 54→	u8 xtal_select = (vga.miscellaneous_output & 0x0c) >> 2;
 55→	int xtal;
 56→
 57→	switch(xtal_select & 3)
 58→	{
 59→		case 0: xtal = XTAL(25'174'800).value() / 3; break;
 60→		case 1: xtal = XTAL(28'636'363).value() / 3; break;
 61→		case 2:
 62→		default:
 63→			throw emu_fatalerror("MN89304: setup ext. clock select");
 64→	}
 65→
 66→	recompute_params_clock(1, xtal);
 67→}
