 68→	// Timer
 69→	emu_timer *m_timer;
 70→	uint16_t m_baud_rate;
 71→
 72→	// Serial RX state
 73→	uint8_t m_rx_clock_count;
 74→	uint8_t m_rx_shift_register;
 75→	uint8_t m_rxd;
 76→	uint8_t m_sioclk_state;
 77→
 78→	// Serial TX state
 79→	uint8_t m_tx_clock_count;
 80→	uint8_t m_tx_shift_register;
 81→	std::queue<uint8_t> m_tx_queue;
 82→	bool m_tx_skip_first_falling;  // Skip first falling edge after pre-outputting bit 0
 83→
 84→	// Command buffer (2-byte commands)
 85→	uint8_t m_cmd_buffer[2];
 86→	uint8_t m_cmd_index;
 87→
 88→	// Protocol state
 89→	bool m_initialized;
 90→	uint8_t m_last_button_state[22];  // 11 segments * 2 panels
 91→
 92→	// Callbacks
 93→	devcb_write_line m_txd_cb;
 94→	devcb_write_line m_sclk_out_cb;
 95→
 96→	// Input port pointers (set by main driver)
 97→	ioport_port *m_cpl_ports[11];  // Left panel segments 0-10
 98→	ioport_port *m_cpr_ports[11];  // Right panel segments 0-10
 99→
100→	// LED outputs
101→	output_finder<50> m_cpl_leds;  // Left panel LEDs (CPL_0 through CPL_49)
102→	output_finder<69> m_cpr_leds;  // Right panel LEDs (CPR_0 through CPR_68)
103→};
