117→void kn5000_cpanel_device::rxd(int state)
118→{
119→	m_rxd = state;
120→}
121→
122→void kn5000_cpanel_device::tx_start(int state)
123→{
124→	// Called when CPU starts transmitting a new byte - reset RX to sync byte boundaries
125→	if (state)
126→	{
127→		LOGMASKED(LOG_SERIAL, "cpanel tx_start: resetting RX counter for sync\n");
128→		m_rx_clock_count = 8;
129→		m_rx_shift_register = 0;
130→	}
131→}
132→
133→void kn5000_cpanel_device::sioclk(int state)
134→{
135→	if (m_sioclk_state == state)
136→		return;
137→
138→	m_sioclk_state = state;
139→
140→	LOGMASKED(LOG_SERIAL, "cpanel sioclk state=%d rxd=%d rx_count=%d tx_count=%d\n",
141→		state, m_rxd, m_rx_clock_count, m_tx_clock_count);
142→
143→	if (state)
144→	{
145→		// Rising edge: Sample RXD (receive bit from CPU)
146→		if (m_rx_clock_count > 0)
147→		{
148→			m_rx_shift_register >>= 1;
149→			m_rx_shift_register |= (m_rxd << 7);
150→			m_rx_clock_count--;
151→
152→			LOGMASKED(LOG_SERIAL, "cpanel RX bit: %d, shift_reg=%02X, count=%d\n",
153→				m_rxd, m_rx_shift_register, m_rx_clock_count);
154→
155→			if (m_rx_clock_count == 0)
156→			{
157→				// Full byte received
158→				m_rx_clock_count = 8;
159→				process_received_byte(m_rx_shift_register);
160→			}
161→		}
162→	}
163→	else
164→	{
165→		// Falling edge: Output TXD (transmit bit to CPU)
166→		// This prepares the bit for the CPU to sample on the next rising edge
167→		if (m_tx_skip_first_falling)
168→		{
169→			// Skip this falling edge - bit 0 was pre-output and we need to give
170→			// CPU a rising edge to sample it before we output bit 1
171→			LOGMASKED(LOG_SERIAL, "cpanel skipping first falling edge (bit 0 already on line)\n");
172→			m_tx_skip_first_falling = false;
173→		}
174→		else if (m_tx_clock_count > 0)
175→		{
176→			// Normal operation: shift out the next bit
177→			m_tx_shift_register >>= 1;
178→			LOGMASKED(LOG_SERIAL, "cpanel TX bit: %d, shift_reg=%02X, count=%d\n",
179→				m_tx_shift_register & 1, m_tx_shift_register, m_tx_clock_count);
180→
181→			m_txd_cb(m_tx_shift_register & 1);
182→			m_tx_clock_count--;
183→
184→			if (m_tx_clock_count == 0)
185→			{
186→				// Byte sent, check for more
187→				if (!m_tx_queue.empty())
188→				{
189→					m_tx_shift_register = m_tx_queue.front();
190→					m_tx_queue.pop();
191→					m_tx_clock_count = 7;  // 7 more bits after pre-outputting bit 0
192→
193→					LOGMASKED(LOG_SERIAL, "cpanel TX next byte: %02X\n", m_tx_shift_register);
194→
195→					// Pre-output first bit of next byte
196→					m_txd_cb(m_tx_shift_register & 1);
197→
198→					// We're in the falling edge handler, so clock is LOW.
199→					// Next edge will be rising (CPU samples bit 0), so no skip needed.
200→					m_tx_skip_first_falling = false;
201→				}
202→				else
203→				{
204→					// Return to idle
205→					LOGMASKED(LOG_SERIAL, "cpanel TX done, returning to idle\n");
206→					m_txd_cb(1);
207→				}
208→			}
209→		}
210→	}
211→}
212→
213→void kn5000_cpanel_device::send_byte(uint8_t data)
214→{
215→	LOGMASKED(LOG_SERIAL, "cpanel send_byte(%02X) tx_count=%d queue_size=%zu sioclk_state=%d\n",
216→		data, m_tx_clock_count, m_tx_queue.size(), m_sioclk_state);
217→
218→	if (m_tx_clock_count == 0 && !m_tx_skip_first_falling)
219→	{
220→		// Start sending immediately
221→		m_tx_shift_register = data;
222→		m_tx_clock_count = 7;  // 7 more bits to send after pre-outputting bit 0
223→
224→		// Pre-output first bit immediately so CPU can sample it on the first rising edge
225→		m_txd_cb(m_tx_shift_register & 1);
226→		LOGMASKED(LOG_SERIAL, "cpanel TX start: byte=%02X, pre-output bit=%d\n",
227→			data, data & 1);
228→
229→		// Only skip the first falling edge if clock is currently HIGH.
230→		// If clock is HIGH: next edge = falling (skip it)
231→		// If clock is LOW: next edge = rising (CPU samples), then falling outputs bit 1 (no skip)
232→		m_tx_skip_first_falling = (m_sioclk_state == 1);
233→		LOGMASKED(LOG_SERIAL, "cpanel TX skip_first_falling=%d\n", m_tx_skip_first_falling);
234→	}
235→	else
236→	{
237→		// Queue for later
238→		m_tx_queue.push(data);
239→		LOGMASKED(LOG_SERIAL, "cpanel TX queued: byte=%02X\n", data);
240→	}
241→}
242→
243→void kn5000_cpanel_device::process_received_byte(uint8_t data)
244→{
245→	LOGMASKED(LOG_SERIAL, "RX byte: %02X (cmd_index=%d)\n", data, m_cmd_index);
246→
247→	m_cmd_buffer[m_cmd_index++] = data;
248→
249→	if (m_cmd_index >= 2)
250→	{
251→		// Full 2-byte command received
252→		process_command();
253→		m_cmd_index = 0;
254→	}
255→}
256→
257→void kn5000_cpanel_device::process_command()
258→{
259→	uint8_t cmd = m_cmd_buffer[0];
260→	uint8_t param = m_cmd_buffer[1];
261→
262→	// Panel selection: bits 7-5 >= 4 means right panel
263→	bool is_right_panel = (cmd & 0xe0) >= 0x80;
264→
265→	LOGMASKED(LOG_COMMANDS, "Command: %02X %02X (%s panel)\n",
266→		cmd, param, is_right_panel ? "right" : "left");
267→
268→	switch (cmd)
269→	{
270→	// Initialization commands
271→	case 0x1f:  // Init sequence (left)
272→	case 0x1d:
273→	case 0x1e:
274→	case 0xdd:  // Setup mode
275→		LOGMASKED(LOG_COMMANDS, "Init command\n");
276→		send_sync_packet();
277→		m_initialized = true;
278→		break;
279→
280→	// Query commands
281→	case 0x20:  // Query left panel
282→	case 0xe0:  // Query right panel
283→		if (param == 0x00)
284→		{
285→			// Ping - respond with sync
286→			send_sync_packet();
287→		}
288→		else if (param <= 0x0a)
289→		{
290→			// Button segment query
291→			send_button_packet(param, !is_right_panel);
292→		}
293→		else if (param == 0x0b || param == 0x10)
294→		{
295→			// Status query
296→			send_sync_packet();
297→		}
298→		break;
299→
300→	case 0x25:  // Left panel data command
301→	case 0xe2:  // Right panel query
302→	case 0xe3:  // Right panel extended query
303→		send_sync_packet();
304→		break;
305→
306→	case 0x2b:  // Init button state array (left)
307→		send_all_button_states(true);
308→		break;
309→
310→	case 0xeb:  // Init button state array (right)
311→		send_all_button_states(false);
312→		break;
313→
314→	// LED control commands - right panel
315→	case 0x00:
316→	case 0x01:
317→	case 0x02:
318→	case 0x03:
319→	case 0x04:
320→	case 0x08:
321→	case 0x0a:
322→	case 0x0b:
323→	case 0x0c:
324→		process_led_command(cmd, param);
325→		send_sync_packet();
326→		break;
327→
328→	// LED control commands - left panel
329→	case 0xc0:
330→	case 0xc1:
331→	case 0xc2:
332→	case 0xc3:
333→	case 0xc4:
334→	case 0xc8:
335→		process_led_command(cmd, param);
336→		send_sync_packet();
337→		break;
338→
339→	default:
340→		// Unknown command - send sync as acknowledgment
341→		LOGMASKED(LOG_COMMANDS, "Unknown command %02X %02X\n", cmd, param);
342→		send_sync_packet();
343→		break;
344→	}
345→}
346→
347→void kn5000_cpanel_device::send_sync_packet()
348→{
349→	// Type 3 sync packet: bits 5-3 = 011 = 0x18
350→	send_byte(0x18);
351→	send_byte(0x00);
352→}
353→
354→uint8_t kn5000_cpanel_device::read_button_segment(int segment, bool is_left_panel)
355→{
356→	if (segment < 0 || segment > 10)
357→		return 0;
358→
359→	ioport_port *port = is_left_panel ? m_cpl_ports[segment] : m_cpr_ports[segment];
360→	if (port)
361→	{
362→		return port->read() & 0xff;
363→	}
364→	return 0;
365→}
366→
367→void kn5000_cpanel_device::send_button_packet(int segment, bool is_left_panel)
368→{
369→	// Button packet format:
370→	// Byte 0: [ Panel | Type | Segment ]
371→	//   - Bit 6: Panel select (0=right, 1=left)
372→	//   - Bits 5-3: Type 0 or 1 (button packet)
373→	//   - Bits 3-0 + bit 6: Segment index
374→	// Byte 1: Button state bitmap
375→
376→	uint8_t state = read_button_segment(segment, is_left_panel);
377→
378→	// For button packets, bit 6 indicates left panel
379→	uint8_t header = (segment & 0x0f);
380→	if (is_left_panel)
381→		header |= 0x40;  // Set bit 6 for left panel
382→
383→	// Type 0 for buttons (bits 5-3 = 000)
384→	send_byte(header);
385→	send_byte(state);
386→
387→	LOGMASKED(LOG_BUTTONS, "Button packet: seg=%d left=%d state=%02X\n",
388→		segment, is_left_panel, state);
389→
390→	// Track state for change detection
391→	int state_idx = is_left_panel ? (segment + 11) : segment;
392→	m_last_button_state[state_idx] = state;
393→}
394→
395→void kn5000_cpanel_device::send_all_button_states(bool is_left_panel)
396→{
397→	// Send all 11 segments for the requested panel
398→	for (int seg = 0; seg <= 10; seg++)
399→	{
400→		send_button_packet(seg, is_left_panel);
401→	}
402→}
403→
404→void kn5000_cpanel_device::process_led_command(uint8_t row, uint8_t data)
405→{
406→	LOGMASKED(LOG_LEDS, "LED command: row=%02X data=%02X\n", row, data);
407→
408→	switch (row)
409→	{
410→	// Right panel LED rows
411→	case 0x00:
412→		m_cpr_leds[1] = BIT(data, 0);  // D101 - EFFECT: SUSTAIN
413→		m_cpr_leds[2] = BIT(data, 1);  // D102 - EFFECT: DIGITAL EFFECT
414→		m_cpr_leds[3] = BIT(data, 2);  // D103 - EFFECT: DSP EFFECT
415→		m_cpr_leds[4] = BIT(data, 3);  // D104 - EFFECT: DIGITAL REVERB
416→		m_cpr_leds[5] = BIT(data, 4);  // D105 - EFFECT: ACOUSTIC ILLUSION
417→		m_cpr_leds[6] = BIT(data, 5);  // D106 - SEQUENCER: PLAY
418→		m_cpr_leds[7] = BIT(data, 6);  // D107 - SEQUENCER: EASY REC
419→		m_cpr_leds[8] = BIT(data, 7);  // D108 - SEQUENCER: MENU
420→		break;
421→
422→	case 0x01:
423→		m_cpr_leds[9] = BIT(data, 0);   // D109 - PIANO
424→		m_cpr_leds[10] = BIT(data, 1);  // D110 - GUITAR
425→		m_cpr_leds[11] = BIT(data, 2);  // D111 - STRINGS & VOCAL
426→		m_cpr_leds[12] = BIT(data, 3);  // D112 - BRASS
427→		m_cpr_leds[13] = BIT(data, 4);  // D113 - FLUTE
428→		m_cpr_leds[14] = BIT(data, 5);  // D114 - SAX & REED
429→		m_cpr_leds[15] = BIT(data, 6);  // D115 - MALLET & ORCH PERC
430→		m_cpr_leds[16] = BIT(data, 7);  // D116 - WORLD PERC
431→		break;
432→
433→	case 0x02:
434→		m_cpr_leds[17] = BIT(data, 0);  // D117 - ORGAN & ACCORDION
435→		m_cpr_leds[18] = BIT(data, 1);  // D118 - ORCHESTRAL PAD
436→		m_cpr_leds[19] = BIT(data, 2);  // D119 - SYNTH
437→		m_cpr_leds[20] = BIT(data, 3);  // D120 - BASS
438→		m_cpr_leds[21] = BIT(data, 4);  // D121 - DIGITAL DRAWBAR
439→		m_cpr_leds[22] = BIT(data, 5);  // D122 - ACCORDION REGISTER
440→		m_cpr_leds[23] = BIT(data, 6);  // D123 - GM SPECIAL
441→		m_cpr_leds[24] = BIT(data, 7);  // D124 - DRUM KITS
442→		break;
443→
444→	case 0x03:
445→		m_cpr_leds[25] = BIT(data, 0);  // D125 - PANEL MEMORY 1
446→		m_cpr_leds[26] = BIT(data, 1);  // D126 - PANEL MEMORY 2
447→		m_cpr_leds[27] = BIT(data, 2);  // D127 - PANEL MEMORY 3
448→		m_cpr_leds[28] = BIT(data, 3);  // D128 - PANEL MEMORY 4
449→		m_cpr_leds[29] = BIT(data, 4);  // D129 - PANEL MEMORY 5
450→		m_cpr_leds[30] = BIT(data, 5);  // D130 - PANEL MEMORY 6
451→		m_cpr_leds[31] = BIT(data, 6);  // D131 - PANEL MEMORY 7
452→		m_cpr_leds[32] = BIT(data, 7);  // D132 - PANEL MEMORY 8
453→		break;
454→
455→	case 0x04:
456→		m_cpr_leds[33] = BIT(data, 0);  // D133 - PART SELECT: LEFT
457→		m_cpr_leds[34] = BIT(data, 1);  // D134 - PART SELECT: RIGHT 2
458→		m_cpr_leds[35] = BIT(data, 2);  // D135 - PART SELECT: RIGHT 1
459→		m_cpr_leds[36] = BIT(data, 3);  // D136 - ENTERTAINER
460→		m_cpr_leds[37] = BIT(data, 4);  // D137 - CONDUCTOR: LEFT
461→		m_cpr_leds[38] = BIT(data, 5);  // D138 - CONDUCTOR: RIGHT 2
462→		m_cpr_leds[39] = BIT(data, 6);  // D139 - CONDUCTOR: RIGHT 1
463→		m_cpr_leds[40] = BIT(data, 7);  // D140 - TECHNI CHORD
464→		break;
465→
466→	case 0x08:
467→		m_cpr_leds[49] = BIT(data, 0);  // D149 - MENU: SOUND
468→		m_cpr_leds[50] = BIT(data, 1);  // D150 - MENU: CONTROL
469→		m_cpr_leds[51] = BIT(data, 2);  // D151 - MENU: MIDI
470→		m_cpr_leds[52] = BIT(data, 3);  // D152 - MENU: DISK
471→		break;
472→
473→	case 0x0a:
474→		m_cpr_leds[57] = BIT(data, 0);  // D157 - MEMORY A
475→		m_cpr_leds[58] = BIT(data, 1);  // D158 - MEMORY B
476→		break;
477→
478→	case 0x0b:
479→		m_cpr_leds[61] = BIT(data, 0);  // D161 - SYNCHRO & BREAK
480→		m_cpr_leds[62] = BIT(data, 1);  // D162 - R1/R2 OCTAVE MINUS
481→		m_cpr_leds[63] = BIT(data, 2);  // D163 - R1/R2 OCTAVE PLUS
482→		m_cpr_leds[64] = BIT(data, 3);  // D164 - BANK VIEW
483→		break;
484→
485→	case 0x0c:
486→		m_cpr_leds[65] = BIT(data, 0);  // D165 - START/STOP 1 BEAT
487→		m_cpr_leds[66] = BIT(data, 1);  // D166 - START/STOP 2 BEAT
488→		m_cpr_leds[67] = BIT(data, 2);  // D167 - START/STOP 3 BEAT
