495→		m_cpl_leds[2] = BIT(data, 1);  // D102 - COMPOSER: MENU
496→		m_cpl_leds[3] = BIT(data, 2);  // D103 - SOUND ARRANGER: SET
497→		m_cpl_leds[4] = BIT(data, 3);  // D104 - SOUND ARRANGER: ON/OFF
498→		m_cpl_leds[5] = BIT(data, 4);  // D105 - MUSIC STYLIST
499→		m_cpl_leds[6] = BIT(data, 5);  // D106 - FADE IN
500→		m_cpl_leds[7] = BIT(data, 6);  // D107 - FADE OUT
501→		m_cpl_leds[8] = BIT(data, 7);  // D108 - DISPLAY HOLD
502→		break;
503→
504→	case 0xc1:
505→		m_cpl_leds[9] = BIT(data, 0);   // D109 - U.S. TRAD
506→		m_cpl_leds[10] = BIT(data, 1);  // D110 - COUNTRY
507→		m_cpl_leds[11] = BIT(data, 2);  // D111 - LATIN
508→		m_cpl_leds[12] = BIT(data, 3);  // D112 - MARCH & WALTZ
509→		m_cpl_leds[13] = BIT(data, 4);  // D113 - PARTY TIME
510→		m_cpl_leds[14] = BIT(data, 5);  // D114 - SHOW TIME & TRAD DANCE
511→		m_cpl_leds[15] = BIT(data, 6);  // D115 - WORLD
512→		m_cpl_leds[16] = BIT(data, 7);  // D116 - CUSTOM
513→		break;
514→
515→	case 0xc2:
516→		m_cpl_leds[17] = BIT(data, 0);  // D117 - STANDARD ROCK
517→		m_cpl_leds[18] = BIT(data, 1);  // D118 - R & ROLL & BLUES
518→		m_cpl_leds[19] = BIT(data, 2);  // D119 - POP & BALLAD
519→		m_cpl_leds[20] = BIT(data, 3);  // D120 - FUNK & FUSION
520→		m_cpl_leds[21] = BIT(data, 4);  // D121 - SOUL & MODERN DANCE
521→		m_cpl_leds[22] = BIT(data, 5);  // D122 - BIG BAND & SWING
522→		m_cpl_leds[23] = BIT(data, 6);  // D123 - JAZZ COMBO
523→		m_cpl_leds[24] = BIT(data, 7);  // D124 - MANUAL SEQUENCE PADS: MENU
524→		break;
525→
526→	case 0xc3:
527→		m_cpl_leds[25] = BIT(data, 0);  // D125 - VARIATION & MSA 1
528→		m_cpl_leds[26] = BIT(data, 1);  // D126 - VARIATION & MSA 2
529→		m_cpl_leds[27] = BIT(data, 2);  // D127 - VARIATION & MSA 3
530→		m_cpl_leds[28] = BIT(data, 3);  // D128 - VARIATION & MSA 4
