532→		m_cpl_leds[30] = BIT(data, 5);  // D130 - AUTO PLAY CHORD
533→		break;
534→
535→	case 0xc4:
536→		m_cpl_leds[33] = BIT(data, 0);  // D133 - FILL IN 1
537→		m_cpl_leds[34] = BIT(data, 1);  // D134 - FILL IN 2
538→		m_cpl_leds[35] = BIT(data, 2);  // D135 - INTRO & ENDING 1
539→		m_cpl_leds[36] = BIT(data, 3);  // D136 - INTRO & ENDING 2
540→		m_cpl_leds[37] = BIT(data, 4);  // D137 - SPLIT POINT INDICATOR (LEFT)
541→		m_cpl_leds[38] = BIT(data, 5);  // D138 - SPLIT POINT INDICATOR (CENTER)
542→		m_cpl_leds[39] = BIT(data, 6);  // D139 - SPLIT POINT INDICATOR (RIGHT)
543→		m_cpl_leds[40] = BIT(data, 7);  // D140 - TEMPO/PROGRAM
544→		break;
545→
546→	case 0xc8:
547→		m_cpl_leds[49] = BIT(data, 0);  // D149 - OTHER PARTS/TR
548→		break;
549→	}
