159→void tmp94c241_serial_device::scNbuf_w(uint8_t data)
160→{
161→	bool was_idle = (m_tx_clock_count == 0);
162→	logerror("buf write: %02X (sioclk_state=%d, was_idle=%d)\n", data, m_sioclk_state, was_idle);
163→
164→	m_tx_shift_register = data;
165→	m_tx_clock_count = 7;  // 7 more bits to send (bits 1-7) after pre-outputting bit 0
166→
167→	// Only signal start of new transmission if we were idle.
168→	// If transmission was in progress, the slave should continue receiving
169→	// (the CPU is replacing the current byte, but byte boundary stays the same)
170→	if (was_idle)
171→	{
172→		m_tx_start_cb(1);
173→	}
174→
175→	// Pre-output first bit immediately so slave can sample it on the first rising edge
176→	logerror("pre-output bit #0: %d\n", m_tx_shift_register & 1);
177→	m_txd_cb(m_tx_shift_register & 1);
178→
179→	// Only skip the first falling edge if clock is currently HIGH AND we were idle.
180→	// If clock is HIGH: next edge = falling (skip it to avoid outputting bit 1 before receiver samples bit 0)
181→	// If clock is LOW: next edge = rising (receiver samples bit 0), then falling outputs bit 1 (no skip needed)
182→	// If we weren't idle: the slave is mid-byte, don't disrupt its counting
183→	m_tx_skip_first_falling = was_idle && (m_sioclk_state == 1);
184→	logerror("skip_first_falling = %d\n", m_tx_skip_first_falling);
185→}
