 74→
 75→void tmp94c241_serial_device::TO2_trigger(int state)
 76→{
 77→	logerror("TO2_trigger state=%d serial_mode=%02X serial_control=%02X\n", state, m_serial_mode, m_serial_control);
 78→	// serial_mode & 3 == 0: TO2 trigger clock source
 79→	// BIT(serial_control, 1) == IOC: 0=SCLK output (master), 1=SCLK input (slave)
 80→	// For master mode with TO2 trigger, IOC should be 0 (NOT set)
 81→	if ((m_serial_mode & 3) == 0 && !BIT(m_serial_control, 1))
 82→	{
 83→		/* Clock source: TO2 output compare trigger, master mode */
 84→		sioclk(state);
 85→	}
 86→}
 87→
 88→void tmp94c241_serial_device::sioclk(int state)
 89→{
 90→	if (m_sioclk_state == state)
 91→		return;
 92→
 93→	m_sioclk_state = state;
 94→
 95→	// Always forward the clock to the slave device - this was missing!
 96→	// The slave needs clock pulses for both RX and TX directions.
 97→	m_sclk_out_cb(state);
 98→
 99→	logerror("sioclk state=%d rxd=%d m_rx_clock_count=%d m_tx_clock_count=%d\n", m_sioclk_state, m_rxd, m_rx_clock_count, m_tx_clock_count);
100→
101→	if (state)
102→	{
103→		// Rising edge: Sample RXD from slave device
104→		if (m_rx_clock_count){
105→			m_rx_clock_count--;
106→
107→			m_rx_shift_register >>= 1;
108→			m_rx_shift_register |= (m_rxd << 7);
109→
110→			if (m_rx_clock_count == 0)
111→			{
112→				m_rx_clock_count = 8;
113→				m_rx_buffer = m_rx_shift_register;
114→				logerror("RX byte received: %02X\n", m_rx_buffer);
115→				m_cpu->m_int_reg[(m_channel == 0) ? INTES0 : INTES1] |= 0x08;
116→				m_cpu->m_check_irqs = 1;
117→			}
118→		}
119→	}
120→	else
121→	{
122→		// Falling edge: Output TXD for slave to sample on next rising edge
123→		if (m_tx_clock_count){
124→			if (m_tx_skip_first_falling) {
125→				// Skip this falling edge - bit 0 was pre-output in scNbuf_w
126→				// and we need to give the receiver a rising edge to sample it
127→				logerror("skipping first falling edge (bit 0 already on line)\n");
128→				m_tx_skip_first_falling = false;
129→			} else {
130→				// Normal operation: shift out the next bit
131→				m_tx_shift_register >>= 1;
132→				logerror("send bit #%d: %d\n", 8-m_tx_clock_count, m_tx_shift_register & 1);
133→
134→				m_txd_cb(m_tx_shift_register & 1);
135→				if (--m_tx_clock_count == 0) {
136→					logerror("Finished sending byte.\n");
137→					// We finished sending the data:
138→					m_cpu->m_int_reg[(m_channel == 0) ? INTES0 : INTES1] |= 0x80;
139→					m_cpu->m_check_irqs = 1;
140→				}
141→			}
142→		}
143→	}
144→}
