**1. Command Processing (lines 257-345):**
```cpp
void kn5000_cpanel_device::process_command()
{
    uint8_t cmd = m_cmd_buffer[0];
    uint8_t param = m_cmd_buffer[1];

    // Panel selection: bits 7-5 >= 4 means right panel
    bool is_right_panel = (cmd & 0xe0) >= 0x80;

    switch (cmd)
    {
    // Initialization commands (0x1F, 0x1D, 0x1E, 0xDD)
    case 0x1f: case 0x1d: case 0x1e: case 0xdd:
        send_sync_packet();
        m_initialized = true;
        break;

    // Query commands (0x20 for left, 0xE0 for right)
    case 0x20: case 0xe0:
        if (param == 0x00) {
            // Ping - respond with sync
            send_sync_packet();
        } else if (param <= 0x0a) {
            // Button segment query
            send_button_packet(param, !is_right_panel);
        }
        break;

    // LED control commands (0x00-0x0C for right, 0xC0-0xC8 for left)
    case 0x00: case 0x01: case 0x02: case 0x03: case 0x04:
    case 0x08: case 0x0a: case 0x0b: case 0x0c:
    case 0xc0: case 0xc1: case 0xc2: case 0xc3: case 0xc4: case 0xc8:
        process_led_command(cmd, param);
        send_sync_packet();
        break;
    }
}
```

**2. Button Packet Generation (lines 367-393):**
```cpp
void kn5000_cpanel_device::send_button_packet(int segment, bool is_left_panel)
{
    uint8_t state = read_button_segment(segment, is_left_panel);

    // Byte 0: [Panel bit | Type | Segment]
    //   - Bit 6: Panel select (0=right, 1=left)
    //   - Bits 5-3: Type 0 (button packet)
    //   - Bits 3-0: Segment index
    uint8_t header = (segment & 0x0f);
    if (is_left_panel)
        header |= 0x40;  // Set bit 6 for left panel

    send_byte(header);
    send_byte(state);
}
```

**3. Serial Clock Handling (lines 133-211):**
```cpp
void kn5000_cpanel_device::sioclk(int state)
{
    if (m_sioclk_state == state)
        return;

    m_sioclk_state = state;

    if (state) {
        // Rising edge: Sample RXD (receive bit from CPU)
        if (m_rx_clock_count > 0) {
            m_rx_shift_register >>= 1;
            m_rx_shift_register |= (m_rxd << 7);
            m_rx_clock_count--;

            if (m_rx_clock_count == 0) {
                // Full byte received
                m_rx_clock_count = 8;
                process_received_byte(m_rx_shift_register);
            }
        }
    } else {
        // Falling edge: Output TXD (transmit bit to CPU)
        if (m_tx_skip_first_falling) {
            m_tx_skip_first_falling = false;
        } else if (m_tx_clock_count > 0) {
            m_tx_shift_register >>= 1;
            m_txd_cb(m_tx_shift_register & 1);
            m_tx_clock_count--;

            if (m_tx_clock_count == 0) {
                // Byte sent, check for more
                if (!m_tx_queue.empty()) {
                    m_tx_shift_register = m_tx_queue.front();
                    m_tx_queue.pop();
                    m_tx_clock_count = 7;
                    m_txd_cb(m_tx_shift_register & 1);
                    m_tx_skip_first_falling = false;
                } else {
                    m_txd_cb(1);  // Return to idle
                }
            }
        }
    }
}
```

**4. LED Control (lines 404-550):**
Maps LED commands to physical LED outputs:
- Right panel: rows 0x00-0x0C
- Left panel: rows 0xC0-0xC8
- Each LED indexed: `m_cpr_leds[index]` or `m_cpl_leds[index]`

