    m_rxd_prev(0),
    m_sioclk_state(0),
    m_tx_clock_count(0),
    m_tx_shift_register(0),
    m_txd(1),  // Idle state is HIGH
    m_sclk_out(0),
    m_tx_skip_first_falling(false)
