**Receive Path (lines 88-144):**
```cpp
void tmp94c241_serial_device::sioclk(int state)
{
    if (m_sioclk_state == state)
        return;

    m_sioclk_state = state;

    // Always forward the clock to the slave device
    m_sclk_out_cb(state);

    if (state) {
        // Rising edge: Sample RXD from slave device
        if (m_rx_clock_count) {
            m_rx_clock_count--;
            m_rx_shift_register >>= 1;
            m_rx_shift_register |= (m_rxd << 7);

            if (m_rx_clock_count == 0) {
                m_rx_clock_count = 8;
                m_rx_buffer = m_rx_shift_register;
                // Trigger RX complete interrupt
                m_cpu->m_int_reg[(m_channel == 0) ? INTES0 : INTES1] |= 0x08;
                m_cpu->m_check_irqs = 1;
            }
        }
    } else {
        // Falling edge: Output TXD for slave to sample on next rising edge
        if (m_tx_clock_count) {
            if (m_tx_skip_first_falling) {
                m_tx_skip_first_falling = false;
            } else {
                m_tx_shift_register >>= 1;
                m_txd_cb(m_tx_shift_register & 1);
                if (--m_tx_clock_count == 0) {
                    // TX complete interrupt
                    m_cpu->m_int_reg[(m_channel == 0) ? INTES0 : INTES1] |= 0x80;
                    m_cpu->m_check_irqs = 1;
                }
            }
        }
    }
}
```

**Transmit Start (lines 159-185):**
```cpp
void tmp94c241_serial_device::scNbuf_w(uint8_t data)
{
    bool was_idle = (m_tx_clock_count == 0);

    m_tx_shift_register = data;
    m_tx_clock_count = 7;  // 7 more bits to send after pre-output bit 0

    if (was_idle) {
        m_tx_start_cb(1);
    }

    // Pre-output first bit immediately
    m_txd_cb(m_tx_shift_register & 1);

    // Skip first falling edge if clock is HIGH AND we were idle
    m_tx_skip_first_falling = was_idle && (m_sioclk_state == 1);
}
```

**Register Access:**
- `scNbuf_r()` (line 154): Read RX buffer
- `scNbuf_w()` (line 159): Write TX buffer (triggers transmission)
- `scNcr_r/w()` (lines 187-196): Serial control register
- `scNmod_r/w()` (lines 198-222): Serial mode register
- `brNcr_r/w()` (lines 224-248): Baud rate register

**Baud Rate Configuration (lines 229-248):**
```cpp
void tmp94c241_serial_device::brNcr_w(uint8_t data)
{
    m_baud_rate = data;
    uint8_t divisor = data & 0x0f;
    uint8_t input_clocks[] = {0, 2, 8, 32};
    uint8_t shift_amount = (((data >> 4) & 3) + 1) * 2;

    if (divisor) {
        long int fc = 16'000'000;  // 16 MHz CPU clock
        m_hz = (fc >> shift_amount) / divisor;
        m_timer->adjust(attotime::from_hz(m_hz), 0, attotime::from_hz(m_hz));
    } else {
        m_timer->reset(attotime::never);
        m_hz = 0;
    }
}
```

